// === Tab: mySketch.js ===
let palette = ['#ff2222', '#ffff22', '#22ff22', '#22ffff', '#2222ff', '#ff22ff'];
let vmin, vmax;
let tex;
let gl, glslFloor, glslLaser;
let camera;
let BPM = 144;
let NUM_LIGHTS = 6;
let overTex;
let mx, my, me = 0.01;
let COLOR, paletteIndex = 0;
let prevLight = false;

function preload() {
  glslFloor = loadShader('https://openprocessing.org/sketch/1357608/files/floor.vert', 'floor.frag');
  glslLaser = loadShader('https://openprocessing.org/sketch/1357608/files/laser.vert', 'laser.frag');
}

function setup() {
  createCanvas(1112, 834);
  smooth();
  noStroke();
  vmin = (width < height) ? width : height;
  vmax = (width > height) ? width : height;
  mx = width / 2;
  my = height / 2;
  palette = shuffle(palette);
  tex = createGraphics(width, height, WEBGL);
  tex.noStroke();
  gl = tex.drawingContext;
  camera = tex.createCamera();
  camera.perspective((90 / 180) * PI, width / height, 0.1, vmax * 5);
  camera.setPosition(0, -vmin * 0.25, vmin * 0.75);
  camera.lookAt(0, 0, 0);

  overTex = createGraphics(width, height);
  overTex.noStroke();
  for (let i = 0; i < (overTex.width * overTex.height) / 5; i++) {
    let x = random(overTex.width);
    let y = random(overTex.height);
    let a = floor(random(20)) * 8 + 8;
    overTex.fill(0, a);
    overTex.square(x, y, 1);
  }

  paletteIndex = 0;
  COLOR = color(palette[paletteIndex]);
}

function laser(x, y, z, size) {
  tex.push();
  {
    gl.colorMask(true, true, true, true);
    tex.translate(x, y - size, z);
    tex.rotateX(PI);
    tex.push();
    {
      let N = 80;
      let radius = vmin * 0.1125;
      tex.translate(0, -size / 2, 0);
      for (let i = 0; i < N; i++) {
        let ni = (i / (N - 1));
        let r = pow(ni, 6) * radius;
        let c = color(palette[paletteIndex]);
        var a = 255 * (1.0 - ni);
        // c.setAlpha(a);
        // tex.fill(...c.levels);
        // tex.fill(255);
        tex.shader(glslLaser);
        glslLaser.setUniform('uTime', millis() / 1000);
        glslLaser.setUniform('uColor', [...COLOR._array.slice(0, 3), a / 255]);
        glslLaser.setUniform('uPos', [x / vmax, y / vmax, z / vmax]);
        // tex.cone(r, size, 24, 1, false);
        tex.cylinder(r, size, 24, 1, false, false);
      }
    }
    tex.pop();
  }
  tex.pop();
}

function drawScene() {
  let sec = millis() / 1000;
  let size = vmin;
  let bLight = sin((sec * PI) * 2 * (BPM / 60)) > -0.5;
  // bLight = true;

  if (bLight && !prevLight) {
    paletteIndex = (paletteIndex + 1) % palette.length;
    COLOR = color(palette[paletteIndex]);
  }

  prevLight = bLight;
  var r = vmin * 0.5;

  mx += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - mx) * me;
  my += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - my) * me;
  let rx = map(my, 0, tex.width, -0.35, 0.25) * PI;
  let ry = map(mx, 0, tex.width, 0.3, -0.3) * PI;

  tex.clear(0);
  tex.background(0);

  tex.push();
  {
    tex.rotateX(rx);
    tex.rotateY(ry);

    let posArr = [];
    for (let i = 0; i < NUM_LIGHTS; i++) {
      var a = i * (TWO_PI / NUM_LIGHTS) - HALF_PI + sec * 1;
      var x = cos(a) * r;
      var y = 0;
      let z = sin(a) * r;
      posArr.push({ x, y, z });
    }

    tex.push();
    {
      tex.translate(0, 0, 0);
      tex.rotateX(PI / 2);
      tex.noStroke();
      tex.fill(255);
      tex.shader(glslFloor);
      glslFloor.setUniform('uColor', COLOR._array);
      for (let i = 0; i < NUM_LIGHTS; i++) {
        var x = bLight ? map(posArr[i].x, -vmax, vmax, 0, 1) : 0;
        var z = bLight ? map(posArr[i].z, -vmax, vmax, 0, 1) : 0;
        glslFloor.setUniform(`uPos${ i }`, [x, z]);
      }
      tex.plane(vmax * 2, vmax * 2);
    }
    tex.pop();

    tex.noLights();
    if (bLight) {
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.SRC_ALPHA, gl.ONE);

      posArr.sort((a, b) => {
        let ad = dist(camera.eyeX, camera.eyeZ, a.x, a.z);
        let bd = dist(camera.eyeX, camera.eyeZ, b.x, b.z);
        return bd - ad;
      });
      for (let { x, y, z } of posArr) {
        laser(x, y, z, size);
      }
      gl.disable(gl.BLEND);
    }
  }
  tex.pop();
}

function draw() {
  drawScene();

  image(tex, 0, 0);

  image(overTex, 0, 0);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  }
}

