precision highp float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
attribute vec3 aNormal;

uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;

varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  vec4 position = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * position;
}

// === Tab: floor.frag ===
precision highp float;

varying vec2 vTexCoord;

uniform sampler2D uTex;
uniform vec4 uColor;
uniform vec2 uPos0;
uniform vec2 uPos1;
uniform vec2 uPos2;
uniform vec2 uPos3;
uniform vec2 uPos4;
uniform vec2 uPos5;
uniform vec2 uPos6;
uniform vec2 uPos7;


void main() {
  vec2 uv = vTexCoord;

  float tex = texture2D(uTex, uv).r;

  float lightMask = 0.;
  if (uPos0.x != 0. && uPos0.y != 0.) {
    float d0 = 0.045 / length(uv - uPos0);
    d0 = pow(d0, 1.5);
    lightMask += d0;
  }
  if (uPos1.x != 0. && uPos1.y != 0.) {
    float d1 = 0.045 / length(uv - uPos1);
    d1 = pow(d1, 1.5);
    lightMask += d1;
  }
  if (uPos2.x != 0. && uPos2.y != 0.) {
    float d2 = 0.045 / length(uv - uPos2);
    d2 = pow(d2, 1.5);
    lightMask += d2;
  }
  if (uPos3.x != 0. && uPos3.y != 0.) {
    float d3 = 0.045 / length(uv - uPos3);
    d3 = pow(d3, 1.5);
    lightMask += d3;
  }
  if (uPos4.x != 0. && uPos4.y != 0.) {
    float d4 = 0.045 / length(uv - uPos4);
    d4 = pow(d4, 1.5);
    lightMask += d4;
  }
  if (uPos5.x != 0. && uPos5.y != 0.) {
    float d5 = 0.045 / length(uv - uPos5);
    d5 = pow(d5, 1.5);
    lightMask += d5;
  }
  if (uPos6.x != 0. && uPos6.y != 0.) {
    float d6 = 0.045 / length(uv - uPos6);
    d6 = pow(d6, 1.5);
    lightMask += d6;
  }
  if (uPos7.x != 0. && uPos7.y != 0.) {
    float d7 = 0.045 / length(uv - uPos7);
    d7 = pow(d7, 1.5);
    lightMask += d7;
  }

  float mask = (tex * pow(lightMask, 2.5)) + (lightMask * 0.1);
  vec3 color = uColor.rgb * mask;

  gl_FragColor = vec4(color, 1.0);
}

